architecture.h4_f:
msg = CBOR{v:1, पाठ, जवाब_दे, भेजल_पर}
सीटी = AES-GCM-256-एन्क्रिप्ट (के, nonce, msg, aad = कमरा_आईडी) बा।
POST /api/rooms/{id}/messages {सिफरटेक्स्ट: हेक्स (सीटी), nonce: हेक्स}

auth.h1_f:
POST /api/प्रमाणीकरण/रजिस्टर के बा
  { यूजरनेम, पासवर्ड, x25519_public_key, display_name, फोन?, ईमेल?, अवतार_इमोजी }

प्रतिक्रिया 201 बनावल गइल:
  { एक्सेस_टोकन, रिफ्रेश_टोकन, यूजर_आईडी, यूजरनेम, ... }

auth.h3_f:
एक्सेस_टोकन पेलोड के बा:
  { उप: उपयोगकर्ता_आईडी, jti: डिवाइस_आईडी, टाइप: "पहुँच", exp: अब + 15min }
ताज़ा_टोकन पेलोड के बा:
  { उप: उपयोगकर्ता_आईडी, jti: डिवाइस_आईडी, टाइप: "ताजा", exp: अब + 30d }

HS256-.env से नोड के 64-बाइट गुप्त के साथ हस्ताक्षरित बा

auth.h7_f:
POST /api/प्रमाणीकरण/qr/शुरुआत होला
  → { nonce: 128-बिट हेक्स, टीटीएल: 60 } के बा।
QR पेलोड = { nonce, यूजर_आईडी, सर्वर: "https://node.example" }

POST /api/प्रमाणीकरण/qr/सत्यापित करीं { nonce }
  → नया डिवाइस पंजीकृत भइल; जेडब्ल्यूटी वापस आ गईले।

rooms.h6_f:
प्रेषक_छद्म = HMAC-SHA256 (कक्ष_छद्म_नमक, प्रेषक_आईडी) [: 16] // 32 हेक्स
ciphertext = AES-GCM-एन्क्रिप्ट (कक्ष_कुंजी, nonce, सीबीओआर_पेलोड, aad = कमरा_आईडी)

फैन-आउट फ्रेम: { प्रकार: "एम", कमरा, संदेश: {आईडी, सीटी, nonce, प्रेषक_छद्म, भेजल_पर} }

calls.h1_f:
POST /api/calls/{room_id}/शुरुआत {वीडियो, ऑडियो} → कॉल_आईडी
WS प्रसारण {प्रकार:"ग", प्रकार:"आमंत्रित", कॉल_आईडी}
WS प्रसारण {प्रकार:"सी", प्रकार:"प्रस्ताव", एसडीपी}
WS प्रसारण {प्रकार:"ग", प्रकार:"उत्तर", एसडीपी}
WS प्रसारण {प्रकार: "ग", प्रकार:"उम्मीदवार", बर्फ} × एन
POST /एपीआई/कॉल/{कॉल_आईडी}/अंत

stealth.h2_f:
ClientHello बाइट्स = क्रोम_120_टेम्पलेट के साथ {
  यादृच्छिक = हमनी के यादृच्छिक,
  server_name = हमनी के होस्टनाम (या ECH-लपेटल),
  session_id = हमनी के सत्र आईडी, 1।
} 1999 में भइल रहे।
JA4 = t13d_xxxx_xxxx_xxxx (वर्तमान क्रोम स्थिर से मेल खाला)

push.h4_f:
आईओएस NSE: didReceive (अनुरोध) { डिक्रिप्ट (अनुरोध.सामग्री.उपयोगकर्ता जानकारी) }
एंड्रॉयड FCM: onMessageReceived (दूरस्थसंदेश) { डिक्रिप्ट (दूरस्थसंदेश.डेटा) }
वेब SW: self.addEventListener ('पुश', ई => डिक्रिप्ट (ई. डेटा)) के बा।

bots.h1_f:
बनाईं: POST /api/bots {उपयोगकर्ता के नाम, प्रदर्शन_नाम, कोड}
          → {बॉट_आईडी, टोकन, पबकी} के बा।
रन: प्रक्रिया में (नोड के अंदर कोरटीन)
      OR बाहरी (लंबा-पोल / api/bots/{id}/अपडेट, टोकन-auth'd)
संदेश: {पाठ, हस्ताक्षर: Ed25519-साइन (बॉट_प्राइव, कैनोनिकल_संदेश)}

bots.h2_f:
पर /शुरुआत { 1000 पर बा।
  emit "स्वागत बा, {ctx.first_name}"।
} 1999 में भइल रहे।
पर /जोड <आइटम> {
  राज्य.सूची = (राज्य.सूची या []) + [ctx.args.item]
  emit "जोड़ल गइल: {ctx.args.item}"।
} 1999 में भइल रहे।

login.h3_f:
{
  "उपयोगकर्ता के नाम": "एलिस",
  "पासवर्ड": "सही घोड़ा बैटरी स्टेपल",
  "totp": "123456" // अगर 2FA सक्षम होखे त जरूरी बा
} 1999 में भइल रहे।

login.h4_f:
सफलता पर: 201 + JWT लिफाफा (रजिस्टर के समान आकार)
2FA पर जरूरत बा: 200 { "needs_2fa": सही } (अभी तक JWT ना)
असफलता पर: 401 { "त्रुटि":"अमान्य_प्रमाणपत्र" }

refresh.h4_f:
{
  "पहुँच_टोकन": "eyJ...",
  "refresh_token": "eyJ..." // तबे जब ROTATE_REFRESH = सही होखे
} 1999 में भइल रहे।

apns.h1_f:
POST https://api.push.apple.com/3/डिवाइस/<डिवाइस_टोकन> के बा
हेडर: apns-विषय: <बंडल_आईडी>, apns-पुश-प्रकार: अलर्ट, apns-ढह-आईडी: कमरा:42
शरीर: {एपीएस: {सचेत: {शीर्षक, शरीर}}, डेटा: <सील कइल गइल>}

controller.h1_f:
GET /v1/integrity → {स्थिति, हस्ताक्षरित_द्वारा, मिलान, बेमेल, ...}
GET /v1/health → {स्थिति, संस्करण, पबकी, आँकड़ा}
GET /v1/प्रविष्टि → [{प्रोटोकॉल, यूआरएल}, ...]।
GET /v1/मिरर → [नियंत्रक_यूआरएल, ...] के बा।

fcm.h1_f:
POST https://fcm.googleapis.com/v1/परियोजना/<परियोजना>/संदेश: भेजल जाला
प्राधिकरण: वाहक <oauth2_token> बा
शरीर: {संदेश: {टोकन: <डिवाइस>, डेटा: {...सील कइल गइल...}, एंड्रॉयड: {collapse_key}}}

fts5.h1_f:
CREATE VIRTUAL TABLE संदेश_फीट USING फुट5(
  सामग्री, -- टोकनाइज्ड कॉलम के बा
  कमरा_आईडी UNINDEXED, 1999 के बा।
  tokenize = 'यूनिकोड61 हटावे_डायक्रिटिक्स 2'।
);
क्वेरी: SELECT rowid FROM संदेश_फीट्स WHERE सामग्री MATCH 'foo'।

gravitix.h1_f:
on /start { emit "स्वागत बा, {ctx.first_name}" }
पर /जोड <आइटम> {
  राज्य.सूची = (राज्य.सूची या []) + [ctx.args.item]
  emit "जोड़ल गइल: {ctx.args.item}"।
} 1999 में भइल रहे।

vapid.h1_f:
VAPID कुंजी: Ed25519 कीपेयर प्रति नोड बा
साइन JWT: {aud: धक्का_सेवा_मूल, exp: अब + 12h, उप: mailto: ops@example}
धक्का अनुरोध हेडर: प्राधिकरण: वैपिड टी = <jwt>, के = <वैपिड_सार्वजनिक_कुंजी>
